{settingsSection==='showcase'&&(<section style={{marginTop:22,padding:22,border:"1px solid #cbbd98",background:"#f2efe5",borderRadius:10}}>
<h2>Homepage Showcase Banner Slider</h2>
<p style={{fontSize:13,color:"#637168",lineHeight:1.7}}>Expertise section ke turant neeche 7–8 wide banner images ka premium slider manage karein. Images Supabase portfolio-media bucket mein upload hongi. Upload ke baad Save Website Settings zaroor karein.</p>
<div className="admin-grid" style={{marginTop:14}}>
<label>Slider heading<input value={settings.home_showcase_heading||"Ideas brought to life."} onChange={e=>setSettings({...settings,home_showcase_heading:e.target.value})}/></label>
<label>Slider introduction<input value={settings.home_showcase_intro||"A closer look at the creative, digital and technology work we bring together."} onChange={e=>setSettings({...settings,home_showcase_intro:e.target.value})}/></label>
<label>Slide interval (seconds)<input type="number" min="3" max="30" value={Math.round(Number(settings.home_showcase_interval||5000)/1000)} onChange={e=>setSettings({...settings,home_showcase_interval:Math.max(3000,Math.min(30000,Number(e.target.value)*1000))})}/></label>
<label>Banner transition effect<select value={settings.home_showcase_transition||"fade"} onChange={e=>setSettings({...settings,home_showcase_transition:e.target.value})}><option value="fade">Fade</option><option value="slide">Slide · Horizontal</option><option value="scroll">Scroll · Vertical</option><option value="zoom-in">Zoom In</option><option value="zoom-out">Zoom Out</option><option value="ken-burns">Ken Burns · Slow Zoom</option><option value="flip">3D Flip</option><option value="blur">Blur Reveal</option></select></label>
<label>Transition speed · {Number(settings.home_showcase_transition_speed||900)} ms<input type="range" min="300" max="2000" step="100" value={settings.home_showcase_transition_speed||900} onChange={e=>setSettings({...settings,home_showcase_transition_speed:Number(e.target.value)})}/></label>
<label>Banner height<select value={settings.home_showcase_height||"standard"} onChange={e=>setSettings({...settings,home_showcase_height:e.target.value})}><option value="compact">Compact</option><option value="standard">Standard</option><option value="large">Large</option></select></label>
<label>Image overlay colour<div style={{display:"flex",gap:8,alignItems:"center",marginTop:6}}><input type="color" value={settings.home_showcase_overlay_color||"#061b13"} onChange={e=>setSettings({...settings,home_showcase_overlay_color:e.target.value})} style={{width:54,height:38,padding:3}}/><input value={settings.home_showcase_overlay_color||"#061b13"} onChange={e=>setSettings({...settings,home_showcase_overlay_color:e.target.value})} placeholder="#061b13"/></div></label>
<label>Overlay darkness · {settings.home_showcase_overlay??42}%<input type="range" min="0" max="85" value={settings.home_showcase_overlay??42} onChange={e=>setSettings({...settings,home_showcase_overlay:Number(e.target.value)})}/></label>
<label style={{display:"flex",alignItems:"center",gap:8}}><input type="checkbox" checked={settings.home_showcase_autoplay!==false} onChange={e=>setSettings({...settings,home_showcase_autoplay:e.target.checked})} style={{width:18}}/> Enable auto sliding</label>
</div>
<label style={{display:"block",marginTop:16}}>Upload multiple banner images (recommended 1920 × 960 px · 6:3 ratio)<input type="file" accept="image/*" multiple onChange={async e=>{const files=Array.from(e.target.files||[]);if(!files.length)return;const current=settings.home_showcase_slides||[];if(current.length+files.length>8){setNotice("Maximum 8 showcase images allowed. Upload fewer images.");e.target.value="";return;}setBusy(true);const added:any[]=[];for(const f of files){const url=await uploadImage(f);if(url)added.push({url,alt:f.name,title:"",subtitle:"",href:"",buttonText:"Explore"});}setSettings((v:any)=>({...v,home_showcase_slides:[...(v.home_showcase_slides||[]),...added]}));setBusy(false);e.target.value="";}}/></label>
<div style={{fontSize:12,color:"#637168",margin:"10px 0"}}>{(settings.home_showcase_slides||[]).length} / 8 banner images added. You can reorder, edit text and links, or remove each slide.</div>
{(settings.home_showcase_slides||[]).map((slide:any,i:number)=><div key={`${slide.url}-${i}`} style={{display:"grid",gridTemplateColumns:"minmax(180px,.8fr) minmax(0,1.5fr)",gap:14,padding:14,marginTop:10,background:"#fffdf7",border:"1px solid #dfd2b9",borderRadius:8}}>
<div><img src={slide.url} alt={slide.alt||"Showcase banner"} style={{width:"100%",aspectRatio:"2 / 1",height:"auto",objectFit:"cover",borderRadius:5}}/><label style={{display:"block",marginTop:8}}>Replace image<input type="file" accept="image/*" onChange={async e=>{const f=e.target.files?.[0];if(f){setBusy(true);const url=await uploadImage(f);if(url)setSettings((v:any)=>{const arr=[...(v.home_showcase_slides||[])];arr[i]={...arr[i],url,alt:f.name};return {...v,home_showcase_slides:arr};});setBusy(false);e.target.value="";}}}/></label><div style={{display:"flex",gap:6,marginTop:8}}><button type="button" className="filter" disabled={i===0} onClick={()=>setSettings((v:any)=>{const arr=[...(v.home_showcase_slides||[])];[arr[i-1],arr[i]]=[arr[i],arr[i-1]];return {...v,home_showcase_slides:arr};})}>← Move</button><button type="button" className="filter" disabled={i===(settings.home_showcase_slides||[]).length-1} onClick={()=>setSettings((v:any)=>{const arr=[...(v.home_showcase_slides||[])];[arr[i+1],arr[i]]=[arr[i],arr[i+1]];return {...v,home_showcase_slides:arr};})}>Move →</button><button type="button" className="filter" onClick={()=>setSettings((v:any)=>({...v,home_showcase_slides:(v.home_showcase_slides||[]).filter((_:any,j:number)=>j!==i)}))}>Delete</button></div></div>
<div className="admin-grid"><label>Slide title<input value={slide.title||""} onChange={e=>setSettings((v:any)=>{const arr=[...(v.home_showcase_slides||[])];arr[i]={...arr[i],title:e.target.value};return {...v,home_showcase_slides:arr};})}/></label><label>Button text<input value={slide.buttonText||"Explore"} onChange={e=>setSettings((v:any)=>{const arr=[...(v.home_showcase_slides||[])];arr[i]={...arr[i],buttonText:e.target.value};return {...v,home_showcase_slides:arr};})}/></label><label style={{gridColumn:"1/-1"}}>Subtitle<input value={slide.subtitle||""} onChange={e=>setSettings((v:any)=>{const arr=[...(v.home_showcase_slides||[])];arr[i]={...arr[i],subtitle:e.target.value};return {...v,home_showcase_slides:arr};})}/></label><label>Click-through link<input value={slide.href||""} placeholder="/portfolio or https://..." onChange={e=>setSettings((v:any)=>{const arr=[...(v.home_showcase_slides||[])];arr[i]={...arr[i],href:e.target.value};return {...v,home_showcase_slides:arr};})}/></label><label>Image alt text<input value={slide.alt||""} onChange={e=>setSettings((v:any)=>{const arr=[...(v.home_showcase_slides||[])];arr[i]={...arr[i],alt:e.target.value};return {...v,home_showcase_slides:arr};})}/></label></div>
</div>)}
</section>)}
