<input value={settings[`${item.key.replace("_hero_image","")}_hero_overlay_color`]||"#071f15"} onChange={e=>setSettings((v:any)=>({...v,[`${item.key.replace("_hero_image","")}_hero_overlay_color`]:e.target.value}))} placeholder="#071f15"/>
